const hexToRgba = (hex, a) => {
  const r = parseInt(hex.slice(1,3),16);
  const g = parseInt(hex.slice(3,5),16);
  const b = parseInt(hex.slice(5,7),16);
  return `rgba(${r},${g},${b},${a})`;
};

const N = 26;
const particles = [];
for (let i=0;i<N;i++){
  particles.push({
    t: Math.random(),
    speed: 0.15 + Math.random()*0.25,
    size: 1.6 + Math.random()*2.4,
    phase: Math.random()*Math.PI*2,
    freq: 1.5 + Math.random()*2.5,
    amp: 18 + Math.random()*46,
    colorIdx: Math.floor(Math.random()*PALETTE.length),
    trail: []
  });
}

const sparkles = [];
for (let i=0;i<12;i++){
  const ang = Math.random()*Math.PI*2;
  const r = 0.3 + Math.random()*0.65;
  sparkles.push({
    ang, r,
    size: 1+Math.random()*2.2,
    speed: 0.5+Math.random()*1.2,
    phase: Math.random()*Math.PI*2,
    colorIdx: Math.floor(Math.random()*PALETTE.length)
  });
}

let t0 = 0;

function frame(){
  t0 += 0.008;
  const w = W(), h = H();
  ctx.clearRect(0,0,w,h);
  const cx = w/2, cy = h/2;
  const centerR = Math.min(w,h)*0.24;

  const len = Math.hypot(w,h);
  const ux = w/len, uy = h/len;
  const beforeX = cx - ux*centerR*1.4, beforeY = cy - uy*centerR*1.4;
  const afterX = cx + ux*centerR*1.4, afterY = cy + uy*centerR*1.4;

  ctx.save();
  ctx.strokeStyle = hexToRgba(PALETTE[1], 0.14);
  ctx.lineWidth = 1;
  ctx.setLineDash([3,10]);
  ctx.lineDashOffset = -t0*50;
  ctx.beginPath();
  ctx.moveTo(0,0);
  ctx.lineTo(beforeX,beforeY);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(afterX,afterY);
  ctx.lineTo(w,h);
  ctx.stroke();
  ctx.restore();

  sparkles.forEach(s=>{
    const rr = Math.min(w,h)*s.r;
    const x = cx + Math.cos(s.ang)*rr*(w>h?1.3:1);
    const y = cy + Math.sin(s.ang)*rr;
    const a = 0.25 + 0.35*Math.sin(t0*s.speed + s.phase);
    if(a<=0) return;
    ctx.beginPath();
    ctx.fillStyle = hexToRgba(PALETTE[s.colorIdx], Math.max(a,0));
    ctx.arc(x,y,s.size,0,Math.PI*2);
    ctx.fill();
  });

  particles.forEach(p=>{
    p.t += p.speed*0.004;
    if(p.t>1.15) p.t -= 1.15;
    const bt = p.t % 1;
    const baseX = bt*w;
    const baseY = bt*h;
    const wobble = Math.sin(bt*p.freq*Math.PI*2 + p.phase + t0*2);
    const x = baseX + wobble*p.amp;
    const y = baseY + Math.cos(bt*p.freq*Math.PI*2 + p.phase*0.6 + t0*1.6)*p.amp*0.4;

    const dist = Math.hypot(x-cx,y-cy);
    let fade = 1;
    if(dist < centerR) fade = Math.max(0, dist/centerR);

    p.trail.push({x,y,fade});
    if(p.trail.length>8) p.trail.shift();

    const col = PALETTE[p.colorIdx];
    for(let i=0;i<p.trail.length;i++){
      const pt = p.trail[i];
      const k = i/p.trail.length;
      const a = k*0.55*pt.fade;
      if(a<=0.01) continue;
      const g = ctx.createRadialGradient(pt.x,pt.y,0,pt.x,pt.y,p.size*3*k+1);
      g.addColorStop(0, hexToRgba(col, a));
      g.addColorStop(1, hexToRgba(col, 0));
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(pt.x,pt.y,p.size*2.4*k+1,0,Math.PI*2);
      ctx.fill();
    }

    if(fade>0.02){
      ctx.save();
      ctx.shadowBlur = 12;
      ctx.shadowColor = hexToRgba(col,0.8*fade);
      ctx.fillStyle = hexToRgba(col, 0.9*fade);
      ctx.beginPath();
      ctx.arc(x,y,p.size,0,Math.PI*2);
      ctx.fill();
      ctx.restore();
    }
  });

  requestAnimationFrame(frame);
}

requestAnimationFrame(frame);
